const products=[
{id:'good-key',name:'按压解压小物',en:'PRESS & RELAX',type:'press',format:'打印成品',color:'#ddd1eb',art:'key',desc:'按一下，给思绪放个小假。',detail:'围绕机械按压触感展开的产品类别。具体造型、规格与配件以商品正式发布为准。',mark:'01'},
{id:'cloud-key',name:'按键挂饰',en:'TAKE JOY WITH YOU',type:'press',format:'打印成品',color:'#f6dfab',art:'cloud',desc:'把一朵软乎乎的好心情，挂在身边。',detail:'将按键玩法带在身边的挂饰类别。具体产品照片、规格与配件以正式发布为准。',mark:'02'},
{id:'spin-ring',name:'旋转解压小物',en:'ROUND & ROUND',type:'spin',format:'打印成品',color:'#f1c6b5',art:'spin',desc:'手指转一圈，日常多一点轻松。',detail:'围绕手指旋转玩法展开的解压小物类别。具体造型、结构与配件以正式发布为准。',mark:'03'},
{id:'good-file',name:'数字设计文件',en:'MAKE YOUR OWN GOOD',type:'file',format:'数字文件',color:'#cfdfcd',art:'file',desc:'用自己的打印机，让一个好点子成形。',detail:'面向希望自行打印和组装的使用者。商品照片、文件格式、配件及授权范围以正式发布为准。',mark:'04'}];
function art(p){if(p.type==='file')return `<span class="photo-slot"><span class="slot-type">虚拟商品</span><strong>设计预览图预留</strong><small>自行打印 · 不含实体产品</small></span>`;return `<span class="photo-slot"><strong>产品照片预留</strong><small>等待实物亮相</small></span>`}

const qs=s=>document.querySelector(s);
const makerWorldProfile='https://makerworld.com/zh/@OGStudio';
// Set verified live product URLs here once the store is open.
const saleLinks={};
let filter='all';
function buyAction(p){const url=saleLinks[p.id];if(url&&/^https:\/\/myship\.7-11\.com\.tw\//.test(url))return `<a class="button yellow" href="${url}" target="_blank" rel="noopener noreferrer">前往 7-ELEVEN 賣貨便购买</a>`;return '<span class="sale-status">尚未开售</span>';}
function renderProducts(){if(!qs('#products'))return;qs('#products').innerHTML=products.filter(p=>document.body.dataset.catalog==='digital'?p.type==='file':p.type!=='file'&&(filter==='all'||p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="查看${p.name}详情">${art(p)}${p.type==='file'?`<span class="card-stamp">${p.format}</span>`:''}<span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>商品类别</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>NT$ · 售价未公布</span><button class="text-button card-details" data-detail="${p.id}">查看详情</button></div></div></article>`).join('');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts();}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return;if(p.type!=='file'){location.href='product.html?id='+encodeURIComponent(id);return;}qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">虚拟商品 · 不含实体产品</span><p class="detail-note">设计文档尚未开售，文件内容与授权以正式发布为准。</p><a class="button mint" href="${makerWorldProfile}" target="_blank" rel="noopener noreferrer">我的 MakerWorld 设计主页</a></div></div>`;qs('#product-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.detail)detail(b.dataset.detail);if(b.hasAttribute('data-close'))b.closest('dialog').close();});
qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
qs('#year').textContent=new Date().getFullYear();renderProducts();
const profileSlot=qs('#makerworld-profile');if(profileSlot){const link=document.createElement('a');link.className='button mint';link.href=makerWorldProfile;link.target='_blank';link.rel='noopener noreferrer';link.textContent='我的 MakerWorld 设计主页';profileSlot.append(link);profileSlot.hidden=false;}
const pageLinks={home:'index.html',products:'products.html',designs:'design-files.html',about:'about.html',product:'products.html'};document.querySelectorAll('header nav a,.catalog-nav a').forEach(a=>{if(a.getAttribute('href')===pageLinks[document.body.dataset.page])a.setAttribute('aria-current','page');});
if(qs('#full-product')){const id=new URLSearchParams(location.search).get('id');const p=products.find(p=>p.id===id&&p.type!=='file');if(!p){qs('#full-product').innerHTML='<h1>没有找到这件商品。</h1><p>请返回实体产品页，重新选择。</p><a class="button yellow" href="products.html">浏览实体产品</a>';}else{document.title=p.name+' — One Goods Studio';qs('#full-product').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en} / ${p.type==='press'?'按压派':'旋转派'}</span><h1>${p.name}</h1><span class="pill">实体产品</span><p>${p.detail}</p><p><strong>NT$ · 售价未公布</strong></p>${buyAction(p)}<div class="product-purchase-note"><b>购买渠道：7-ELEVEN 賣貨便</b><p class="detail-note">产品照片、材质、尺寸及售价以正式发布为准。当前尚未开售。</p></div></div></div>`;}}
